    url: "https://www.blum.com.cn/cn/zh/products/motion-technologies/blumotion/overview/",
    summary:
      "BLUMOTION 是 Blum 自研的油压阻尼闭合技术，通过内置于产品内部的油压缓冲器实现轻柔、无冲击的关闭效果。其工作原理是利用硅油通过精密节流孔时的粘滞阻力，将动能转化为热能缓慢释放，从而在最后 30~50mm 的行程范围内持续减速直至完全关闭。BLUMOTION 的关键参数：适用关闭速度范围 0.3~1.5m/s，阻尼力矩可调节 1~5 档（通过旋转调节螺丝），适用温度范围 -30°C~+80°C，适用产品包括铰链（CLIP top BLUMOTION）、抽屉（内置于 MOVENTO、TANDEMBOX、LEGRABOX、MERIVOBOX 导轨）和上翻门（AVENTOS 全系列内置）。BLUMOTION 不可后加装（必须在采购时选择对应型号），但可在使用中通过调节螺丝进行微调以适应不同面板重量。阻尼失效的常见原因包括：温度极端导致硅油黏度变化（寒冷环境黏度增大，关闭变慢；高温环境黏度降低，阻尼减弱）、长期使用后硅油微量渗漏（不可维修，需更换整个阻尼单元）。",
