    id: "aventos-adjustment",
    title: "AVENTOS 上翻门力矩设置与调节",
    url: "https://www.blum.com/us/en/services/e-services/easyassemblyapp/",
    summary:
      "AVENTOS 上翻门的力矩设置是安装中最关键的步骤，力矩过小会导致门板无法维持开启位置（自行下落），力矩过大会导致开启阻力过大。省力装置的力矩等级选择基于力矩计算公式：力矩(Nm) = 面板重量(kg) × 9.8 × 面板重心高度(m)。计算后对照省力装置等级表（LS/S/M/H/HL）选择最接近且偏大的等级。省力装置本身还提供 ±15% 的微调范围：通过旋转调节螺丝调整弹簧预紧力（顺时针增加力矩，逆时针减小力矩）。安装完成后需要进行开启测试：门板从完全关闭位置手动开启至全开位置，松开后门板应能在任意中间位置稳定悬停（不自行下落也不自行上升），如不符合则需微调力矩。省力装置左右两只必须同时调节且调节量一致，否则会导致门板歪斜。BLUMOTION 阻尼的调节通过 AVENTOS 本体侧面的独立调节螺丝进行，范围 1~5 档，与抽屉阻尼调节方法相同。",
